from decimal import Decimal, ROUND_HALF_UP, InvalidOperation

def calc_total(items: list[dict]) -> str:
    total = Decimal('0')
    for item in items:
        price = item.get('price')
        if price is None:
            raise ValueError('Each item must have a price.')
        qty = item.get('qty')
        if qty is None:
            raise ValueError('Each item must have a quantity.')

        try:
            price_decimal = Decimal(price)
        except InvalidOperation:
            raise ValueError('Price must be a nonnegative finite decimal string.')

        if not price_decimal.is_finite() or price_decimal < 0:
            raise ValueError('Price must be a nonnegative finite decimal string.')

        if not isinstance(qty, int) or isinstance(qty, bool) or qty < 0:
            raise ValueError('Quantity must be a nonnegative integer.')

        total += (price_decimal * qty).quantize(Decimal('0.01'), rounding=ROUND_HALF_UP)

    return str(total.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))

